describe('Notification Preferences Management', () => {
  beforeEach(() => {
    cy.visit('/settings/notifications');
    cy.get('[data-testid="notification-preferences-container"]').should('be.visible');
  });

  it('should display all notification preference options and allow user to toggle them', () => {
    // Verify all notification categories are displayed
    cy.get('[data-testid="notification-category"]').should('have.length.greaterThan', 0);

    // Verify email notifications toggle exists
    cy.get('[data-testid="email-notifications-toggle"]').should('be.visible');

    // Verify push notifications toggle exists
    cy.get('[data-testid="push-notifications-toggle"]').should('be.visible');

    // Verify SMS notifications toggle exists
    cy.get('[data-testid="sms-notifications-toggle"]').should('be.visible');

    // Toggle email notifications off
    cy.get('[data-testid="email-notifications-toggle"]').click();
    cy.get('[data-testid="email-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');

    // Toggle push notifications on
    cy.get('[data-testid="push-notifications-toggle"]').click();
    cy.get('[data-testid="push-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');

    // Verify save button is visible and enabled
    cy.get('[data-testid="save-preferences-btn"]').should('be.visible').and('be.enabled');

    // Click save button
    cy.get('[data-testid="save-preferences-btn"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Preferences saved successfully');
  });

  it('should handle granular notification preferences by category and frequency', () => {
    // Expand marketing notifications category
    cy.get('[data-testid="notification-category-marketing"]').click();
    cy.get('[data-testid="marketing-subcategories"]').should('be.visible');

    // Verify frequency options are available
    cy.get('[data-testid="frequency-select-marketing"]').should('be.visible');
    cy.get('[data-testid="frequency-select-marketing"]').click();
    cy.get('[data-testid="frequency-option-weekly"]').click();
    cy.get('[data-testid="frequency-select-marketing"]').should('contain', 'Weekly');

    // Expand product updates category
    cy.get('[data-testid="notification-category-product"]').click();
    cy.get('[data-testid="product-subcategories"]').should('be.visible');

    // Toggle specific product update notification
    cy.get('[data-testid="notification-product-new-features"]').click();
    cy.get('[data-testid="notification-product-new-features"]').should('have.attr', 'aria-checked', 'true');

    // Verify unsubscribe all button exists
    cy.get('[data-testid="unsubscribe-all-btn"]').should('be.visible');

    // Save preferences
    cy.get('[data-testid="save-preferences-btn"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');

    // Verify preferences persist on page reload
    cy.reload();
    cy.get('[data-testid="frequency-select-marketing"]').should('contain', 'Weekly');
    cy.get('[data-testid="notification-product-new-features"]').should('have.attr', 'aria-checked', 'true');
  });

  it('should display validation error when no notification method is selected', () => {
    // Disable all notification methods
    cy.get('[data-testid="email-notifications-toggle"]').then(($toggle) => {
      if ($toggle.attr('aria-checked') === 'true') {
        cy.get('[data-testid="email-notifications-toggle"]').click();
      }
    });

    cy.get('[data-testid="push-notifications-toggle"]').then(($toggle) => {
      if ($toggle.attr('aria-checked') === 'true') {
        cy.get('[data-testid="push-notifications-toggle"]').click();
      }
    });

    cy.get('[data-testid="sms-notifications-toggle"]').then(($toggle) => {
      if ($toggle.attr('aria-checked') === 'true') {
        cy.get('[data-testid="sms-notifications-toggle"]').click();
      }
    });

    // Attempt to save
    cy.get('[data-testid="save-preferences-btn"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'At least one notification method must be selected');

    // Verify save button is disabled
    cy.get('[data-testid="save-preferences-btn"]').should('be.disabled');
  });

  it('should allow user to reset preferences to default settings', () => {
    // Change some preferences
    cy.get('[data-testid="email-notifications-toggle"]').click();
    cy.get('[data-testid="push-notifications-toggle"]').click();

    // Click reset button
    cy.get('[data-testid="reset-preferences-btn"]').click();

    // Verify confirmation dialog appears
    cy.get('[data-testid="reset-confirmation-dialog"]').should('be.visible');
    cy.get('[data-testid="reset-confirmation-dialog"]').should('contain', 'Are you sure you want to reset to default settings?');

    // Confirm reset
    cy.get('[data-testid="confirm-reset-btn"]').click();

    // Verify preferences are reset
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Preferences reset to defaults');

    // Reload and verify defaults are applied
    cy.reload();
    cy.get('[data-testid="email-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');
    cy.get('[data-testid="push-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');
  });
});
